import { Component, OnInit} from '@angular/core';
import { ViewEncapsulation, ChangeDetectionStrategy } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { BaseClassTemplate } from '@_core/__base';

import { TMSubmit } from '@_core/_form';
import { URL_CONTRL, URL_SRVC } from '@_core/_client';
import { MyForm } from './form';


@Component({
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'aam-classz-add',
  templateUrl: './classz-add.component.html',
})
export class ClasszAdd extends BaseClassTemplate implements OnInit {
  constructor(private route: ActivatedRoute) {
    super();
  }

  ngOnInit(): void {
    this.InitForm();
  }
  InitForm(){
    MyForm(this);
    this._template.fsb = new TMSubmit(this, {
      srvc: URL_SRVC.Edu,
      cntrl: URL_CONTRL.Edu.Classz,
    })
    .init();


    this._template.fsb.httpResSingle.subscribe({
      next: (d) => this._fs._form.patchValue(d)
    })
  }
  onEdit() {

  }

}
