import { BaseClassTemplate } from '@_core/__base';
import { URL_CONTRL, URL_SRVC } from '@_core/_client';
import { TM_List } from '@_core/_pagination';
import {
  ChangeDetectionStrategy,
  Component,
  OnInit,
  ViewEncapsulation,
} from '@angular/core';

@Component({
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'aam-institute',
  templateUrl: './institute.component.html',
})
export class InstituteComponent extends BaseClassTemplate implements OnInit {
  ngOnInit() {
    this.initTables();
  }
  initTables() {
    this._template.lb = new TM_List(this,
      {
        srvc: URL_SRVC.Edu,
        cntrl: URL_CONTRL.Edu.Institute,
      },
      [
        { key: 'branch', name: 'Branch'},
        { key: 'address', name: 'Address'},
        { key: 'nearby', name: 'Near By Place'},
        { key: 'loction', name: 'Location'},
        { key: 'image', name: 'Image'},
      ],
    ).init();
  }
}
